/// <summary>
/// PaffH 03.02.22
/// initialize connectionStringNDX365FO01NS once
/// </summary>
static void TypeNew()
{
    try
    {
        NDXKeyVaultSecretNameConnectionStringNDX365FO01NS nDXKeyVaultSecretNameConnectionStringNDX365FO01NS = NDXProdIdentControlPanelParameters::find().KeyVaultSecretNameConnectionStringNDX365FO01NSD365FO;
        if (!nDXKeyVaultSecretNameConnectionStringNDX365FO01NS)
        {
            error(strFmt("@NDXBase:NDXInformationIsMissing", "@NDXBase:NDXKeyVaultSecretNameConnectionStringNDX365FO01NS"));
            connectionStringNDX365FO01NS = '';
        }
        else
        {
            connectionStringNDX365FO01NS = NDXKeyVaultHelper::GetKeyVaultSecretValueFromD365FO(nDXKeyVaultSecretNameConnectionStringNDX365FO01NS);
        }
    }
    catch
    {
        connectionStringNDX365FO01NS = '';
    }

    if (!connectionStringNDX365FO01NS)
    {
        //connectionStringNDX365FO01NS = NDXKeyVaultHelper::getKeyVaultSecretValue('https://azr-servicebus-vault.vault.azure.net/', 'NDX365FO01NS-ConnectionString');
        connectionStringNDX365FO01NS = NDXKeyVaultHelper::getKeyVaultSecretValue(
            NDXProdIdentControlPanelParameters::find().AzureKeyVaultServiceBusURI,
            NDXProdIdentControlPanelParameters::find().KeyVaultSecretNameConnectionStringNDX365FO01NS);
            //'https://azr-servicebus-vault.vault.azure.net/', 'NDX365FO01NS-ConnectionString');
    }
    //serviceBusQueueName = 'palabelsaved2ndxdatabase';
    serviceBusQueueName = NDXProdIdentControlPanelParameters::find().AzureServiceBusQueueNameLabelInfoHandshake;
    if (!serviceBusQueueName)
    {
        error(strFmt("@NDXBase:NDXInformationIsMissing", "@NDXBase:NDXAzureServiceBusLabelInfoHandshake"));
        connectionStringNDX365FO01NS = '';
    }
}

